pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 drugs, uint256 seedDrugs) public {
        // Keep drugs within admissible domain
        vm.assume(seedDrugs > 0);
        vm.assume(drugs > 0);
        // Setup: seed the market once to set marketDrugs > 0
        vm.assume(seedDrugs <= type(uint256).max / 2);
        c.seedMarket{value: 0}(seedDrugs);
        // Now marketDrugs > 0, so a second seedMarket call should revert
        bool secondSeedReverted;
        try c.seedMarket{value: 0}(drugs) {
            secondSeedReverted = false;
        } catch {
            secondSeedReverted = true;
        }
        // If we are in a context where initialized should still be false (second call reverted),
        // then collectDrugs must also revert
        bool collectReverted;
        try c.collectDrugs(address(0)) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        // Property: If seedMarket reverts, initialized must remain false,
        // so collectDrugs (which requires initialized) must also revert.
        // The bug makes initialized true even on revert, so collectDrugs succeeds.
        assertTrue(!(secondSeedReverted && !collectReverted));
    }
}

