pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 drugs, uint256 seedDrugs, address ref) public {
        vm.assume(ref != address(0) && ref != address(c) && ref != address(this));
        vm.assume(seedDrugs > 0 && drugs > 0);

        // Seed the market once legitimately to make marketDrugs > 0
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 0}(seedDrugs);

        // The buggy version sets initialized=true even when the second seedMarket reverts.
        // A re-entrant attacker that calls collectDrugs during the fallback of a transfer
        // can then succeed only if initialized becomes true.
        ReentrantAttacker attacker = new ReentrantAttacker(c, ref);
        vm.deal(address(attacker), 1 ether);

        // The attacker tries to trigger seedMarket with a value that reverts (marketDrugs > 0).
        // The attacker's fallback calls collectDrugs, which requires initialized.
        // If initialized is set to true by the buggy seedMarket despite the revert,
        // collectDrugs will succeed and claimedDrugs[ref] will increase.
        uint256 beforeClaimed = c.claimedDrugs(ref);

        bool ok;
        try attacker.attack{value: 0}(drugs) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference always reverts the attack, so claimedDrugs[ref] never increases.
        // Buggy version sometimes allows collectDrugs to execute, increasing claimedDrugs[ref].
        // Since the attack always reverts in the reference, ok should be false.
        // But if ok becomes true (re-entrancy succeeded), claimedDrugs[ref] would have increased.
        // We assert that either the attack failed, or claimedDrugs[ref] did not increase.
        assertTrue(!ok || c.claimedDrugs(ref) == beforeClaimed);
    }
}

contract ReentrantAttacker {
    C c;
    address ref;
    bool attacking;

    constructor(C _c, address _ref) {
        c = _c;
        ref = _ref;
    }

    function attack(uint256 drugs) external payable {
        attacking = true;
        // This call will revert because marketDrugs > 0, but the bug sets initialized=true
        // before the require fails, so during the transfer of the fee inside buyDrugs
        // (or if we directly call seedMarket, no external call happens).
        // To exploit the bug, we need an external call that occurs after initialized=true
        // but before the revert. seedMarket doesn't make external calls.
        // However, the bug affects subsequent calls. So we just call seedMarket here,
        // it reverts, but initialized becomes true in the buggy version.
        // Then we call collectDrugs in the fallback, which will succeed if initialized is true.
        c.seedMarket{value: msg.value}(drugs);
        attacking = false;
    }

    fallback() external payable {
        if (attacking) {
            attacking = false;
            c.collectDrugs(ref);
        }
    }
}

